class Stack:
    def __init__(self):
        self.items = []   # top = end

    def push(self, x):
        self.items.append(x)   # O(1)*

    def pop(self):
        if not self.items:
            raise IndexError("underflow")
        return self.items.pop()   # O(1)

    def peek(self):
        if not self.items:
            raise IndexError("underflow")
        return self.items[-1]

def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)

fact(3)   # main → fact(3) → fact(2) → fact(1)

def f(n):
    return f(n + 1)   # never stops

f(1)   # RecursionError
